// The AI is asked for pure JSON, but models sometimes add ```json fences or a sentence around it.
// Keep only what is between the first "{" and the last "}" before parsing.
const raw = $json.text || '';
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

try {
  const ai = JSON.parse(raw.slice(start, end + 1));
  return {
    json: {
      category: ai.category || 'other',
      urgency: ai.urgency || 'medium',
      missing_info: ai.missing_info === true,
      reply: ai.reply || '',
    },
  };
} catch (error) {
  // Invalid JSON: never lose a customer email. Create a draft asking for a manual answer instead.
  return {
    json: {
      category: 'parse_error',
      urgency: 'medium',
      missing_info: true,
      reply: '[AI ERROR: no reply could be generated for this email. Please answer it manually.]',
    },
  };
}
